const {esc,api,toast,modalWide,closeModal}=window;
let c08ProjectPackage=null;
async function c08json(path,opts={}){const r=await fetch(path,opts);const ct=r.headers.get('content-type')||'';const b=ct.includes('json')?await r.json():await r.text();if(!r.ok)throw new Error(b?.detail||b?.error?.code||String(b));return b}
window.c08OpenProjectImport=()=>{c08ProjectPackage=null;modalWide('导入完整项目包',`<div class="form-grid"><div class="field full"><label>SRW Project Package</label><input id="c08-project-package" class="input" type="file" accept=".zip,.srwproject.zip,application/zip"></div><div class="field full"><div class="status warn" style="display:block">项目包包含候选人个人数据、原始材料和招聘业务记录。只应在受控环境中传输。</div></div><div id="c08-project-preview" class="field full"><div class="empty">先 Preview。系统会校验 ZIP 路径、成员清单、Schema、Blob SHA-256，并锁定整个文件摘要；只有完全相同的文件才能 Commit。</div></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn" onclick="c08PreviewProjectPackage()">Preview</button><button id="c08-project-commit" class="btn primary" disabled onclick="c08CommitProjectPackage()">Commit 导入</button>`)};
window.c08PreviewProjectPackage=async()=>{const f=document.querySelector('#c08-project-package')?.files?.[0];if(!f){toast('请选择项目包',true);return}try{const bytes=await f.arrayBuffer();const r=await c08json('/api/v1/projects/import-package/preview',{method:'POST',headers:{'Content-Type':'application/zip'},body:bytes});c08ProjectPackage={file:f,bytes,digest:r.sha256,preview:r};const counts=Object.entries(r.table_counts||{}).filter(([,v])=>Number(v)>0);document.querySelector('#c08-project-preview').innerHTML=`<div class="status good">包完整性校验通过</div><div class="subtle" style="margin-top:8px">项目：${esc(r.project_title)} · ${(r.size_bytes/1024/1024).toFixed(2)} MB · Blob ${r.blob_count}</div><div class="mono subtle" style="margin-top:4px">SHA-256 ${esc(r.sha256)}</div><div class="divider"></div><div class="quick-list">${counts.slice(0,30).map(([k,v])=>`<div class="quick-item"><span>${esc(k)}</span><strong>${v}</strong></div>`).join('')}</div><div class="divider"></div><div class="status warn" style="display:block">导入会重映射所有业务 ID。历史 Decision Context 保留为 historical，导入后必须在新上下文重新评价；不会把旧决定伪装成当前决定。</div>`;document.querySelector('#c08-project-commit').disabled=false}catch(e){c08ProjectPackage=null;document.querySelector('#c08-project-commit').disabled=true;toast(e.message,true)}};
window.c08CommitProjectPackage=async()=>{if(!c08ProjectPackage){toast('请先 Preview 完整项目包',true);return}if(!confirm('确认导入？项目包含个人数据；所有 ID 会重映射，历史判断保持 historical，当前上下文需要重新评价。'))return;try{const r=await c08json('/api/v1/projects/import-package',{method:'POST',headers:{'Content-Type':'application/zip','X-SRW-Package-SHA256':c08ProjectPackage.digest,'X-SRW-Actor':'human'},body:c08ProjectPackage.bytes});closeModal();toast(`项目已导入：${r.title}`);setTimeout(()=>window.go?.('projects'),250)}catch(e){toast(e.message,true)}};
window.c08ExportProjectPackage=id=>{if(!id)return;toast('正在生成完整项目包；其中包含个人数据');window.location.href=`/api/v1/projects/${encodeURIComponent(id)}/export-package`};
